class DataTransferStopFailedTwice(TafUeAtcmdError):
    """Raises when stopping data transfer failed both on server and client sides."""
    def __init__(self, client_exc, client_traceback, server_exc, server_traceback, ):
        """
        Basic initialization
        :param client_exc: exception raises during stopping data transfer on client
        :param client_traceback: traceback for exception raises during stopping data transfer on server
        :param server_exc: exception raises during stopping data transfer on server
        :param server_traceback: traceback for exception raises during stopping data transfer on server
        """
        err_msg = f"Stopping data transfer failed both on server and client sides: " \
                  f"\nServer exception: {server_exc}, \n{server_traceback}" \
                  f"\nClient exception: {client_exc}, \n{client_traceback}"
        super().__init__(err_msg)


