class UnsupportedIperfVersionException(Exception):
    """Unsupported iperf version"""

    def __init__(self, version, supported_versions):
        super().__init__(
            f"Requested ver. of iperf\"{version}\" is unsupported. Currently supported versions: "
            f"{', '.join(map(str, supported_versions))}")


